EXM18 - AI Observability	f	[{"parameters":{"jsCode":"/*\\n * Candid GRC Co., Ltd.\\n * Copyright © 2026 Candid GRC Co., Ltd.\\n * All Rights Reserved.\\n *\\n * This source code is proprietary and confidential.\\n * Unauthorized copying, modification, redistribution,\\n * reverse engineering, or commercial use is strictly prohibited.\\n *\\n * This code forms part of the Candid GRC Automation Framework.\\n */\\n\\nconst now = new Date();\\nconst body = $json.body || {};\\nconst prompt =\\n  body.prompt ||\\n  body.message ||\\n  $json.prompt ||\\n  $json.message ||\\n  $input.first().json.chatInput ||\\n  \\"\\";\\n\\nif (!String(prompt).trim()) {\\n  throw new Error(\\"Missing prompt/message in request body\\");\\n}\\n\\nconst sessionId = body.sessionId || body.session_id || \\"session-\\" + Date.now();\\nconst userId = body.userId || body.user_id || \\"anonymous\\";\\nconst requestId = body.requestId || \\"req-\\" + Date.now();\\n\\nreturn [\\n  {\\n    json: {\\n      requestId: String(requestId),\\n      sessionId: String(sessionId),\\n      userId: String(userId),\\n      model: body.model || \\"models/gemini-2.5-flash\\",\\n      chatInput: String(prompt),\\n      startTs: now.getTime(),\\n      timestamp: now.toISOString(),\\n      source: \\"chat\\",\\n    },\\n  },\\n];\\n"},"id":"1d675026-3b53-4b61-84f5-6d77f1e865a7","name":"Prepare Input + Start Timer","type":"n8n-nodes-base.code","typeVersion":2,"position":[848,1328]},{"parameters":{"options":{}},"id":"d1e7a1da-adaf-4618-a443-e25205efb81c","name":"Gemini 2.5 Flash","type":"@n8n/n8n-nodes-langchain.lmChatGoogleGemini","typeVersion":1,"position":[1088,1552],"credentials":{"googlePalmApi":{"id":"KCNl8nll2LdXHyBa","name":"Google Gemini(PaLM) Api account [TK]"}}},{"parameters":{"jsCode":"/*\\n * Candid GRC Co., Ltd.\\n * Copyright © 2026 Candid GRC Co., Ltd.\\n * All Rights Reserved.\\n *\\n * This source code is proprietary and confidential.\\n * Unauthorized copying, modification, redistribution,\\n * reverse engineering, or commercial use is strictly prohibited.\\n *\\n * This code forms part of the Candid GRC Automation Framework.\\n */\\n\\nconst req = $(\\"Prepare Input + Start Timer\\").first().json;\\nconst out = $input.first().json || {};\\n\\nfunction safeNodeJson(nodeName) {\\n  try {\\n    return $(nodeName).first().json || {};\\n  } catch (e) {\\n    return {};\\n  }\\n}\\n\\nfunction safeNodeJsonItems(nodeName) {\\n  try {\\n    return $(nodeName)\\n      .all()\\n      .map((item) => item.json || {});\\n  } catch (e) {\\n    return [];\\n  }\\n}\\n\\nconst modelItems = safeNodeJsonItems(\\"Gemini 2.5 Flash\\");\\nconst rawAgent = safeNodeJson(\\"AI Agent\\");\\n\\nfunction findUsage(obj, depth = 0) {\\n  if (!obj || typeof obj !== \\"object\\" || depth > 5) return null;\\n\\n  const candidates = [\\n    obj.tokenUsage,\\n    obj.usageMetadata,\\n    obj.usage,\\n    obj.response?.usageMetadata,\\n    obj.response_metadata?.usage,\\n    obj.metadata?.usageMetadata,\\n    obj.metadata?.tokenUsage,\\n    obj.additional_kwargs?.usage,\\n    obj.additional_kwargs?.usageMetadata,\\n    obj.data?.usageMetadata,\\n    obj.data?.usage,\\n  ].filter(Boolean);\\n\\n  for (const c of candidates) {\\n    if (typeof c === \\"object\\") return c;\\n  }\\n\\n  for (const value of Object.values(obj)) {\\n    if (value && typeof value === \\"object\\") {\\n      const found = findUsage(value, depth + 1);\\n      if (found) return found;\\n    }\\n  }\\n\\n  return null;\\n}\\n\\nfunction firstUsageFromItems(items) {\\n  for (let i = items.length - 1; i >= 0; i--) {\\n    const found = findUsage(items[i]);\\n    if (found) return found;\\n  }\\n  return null;\\n}\\n\\nfunction toNum(v, d = 0) {\\n  const n = Number(v);\\n  return Number.isFinite(n) ? n : d;\\n}\\n\\nconst usageFromChatModel = firstUsageFromItems(modelItems) || {};\\nconst usageFromAgent = findUsage(rawAgent) || {};\\nconst usageFromParsedOutput = findUsage(out) || {};\\nconst usageFromAnswer =\\n  out.tokenUsage && typeof out.tokenUsage === \\"object\\" ? out.tokenUsage : {};\\n\\nconst usage = Object.keys(usageFromChatModel).length\\n  ? usageFromChatModel\\n  : Object.keys(usageFromAgent).length\\n    ? usageFromAgent\\n    : Object.keys(usageFromParsedOutput).length\\n      ? usageFromParsedOutput\\n      : usageFromAnswer;\\n\\nconst inputTokens = toNum(\\n  usage.promptTokens ??\\n    usage.promptTokenCount ??\\n    usage.inputTokens ??\\n    usage.prompt_tokens ??\\n    usage.input_tokens,\\n  0,\\n);\\nconst outputTokens = toNum(\\n  usage.completionTokens ??\\n    usage.candidatesTokenCount ??\\n    usage.outputTokens ??\\n    usage.completion_tokens ??\\n    usage.output_tokens,\\n  0,\\n);\\nconst totalTokens = toNum(\\n  usage.totalTokens ??\\n    usage.totalTokenCount ??\\n    usage.total_tokens ??\\n    usage.totalToken,\\n  inputTokens + outputTokens,\\n);\\n\\nconst claims = Array.isArray(out.factual_claims) ? out.factual_claims : [];\\nconst unsupportedClaims = claims.filter((c) => {\\n  const status = String(c?.support_status || \\"\\").toLowerCase();\\n  return status === \\"unsupported\\" || status === \\"unknown\\";\\n}).length;\\nconst hallucinationRate =\\n  claims.length > 0\\n    ? Number((unsupportedClaims / claims.length).toFixed(4))\\n    : null;\\n\\nconst responseText =\\n  out.answer || out.output || out.text || out.response || out.result || \\"\\";\\nconst latencyMs = Date.now() - Number(req.startTs || Date.now());\\nconst biasRisk = String(out.bias_risk || \\"unknown\\").toLowerCase();\\nconst hallucinationRisk = String(\\n  out.hallucination_risk || \\"unknown\\",\\n).toLowerCase();\\n\\nconst autoNeedsReview =\\n  (hallucinationRate !== null && hallucinationRate > 0.2) ||\\n  biasRisk === \\"high\\" ||\\n  hallucinationRisk === \\"high\\";\\nconst needsReview = Boolean(out.needs_review) || autoNeedsReview;\\n\\nlet tokenSource = \\"not-available\\";\\nif (Object.keys(usageFromChatModel).length) tokenSource = \\"chat-model-node\\";\\nelse if (Object.keys(usageFromAgent).length)\\n  tokenSource = \\"agent-node-metadata\\";\\nelse if (Object.keys(usageFromParsedOutput).length)\\n  tokenSource = \\"parsed-output-metadata\\";\\nelse if (Object.keys(usageFromAnswer).length) tokenSource = \\"agent-self-report\\";\\n\\nreturn [\\n  {\\n    json: {\\n      timestamp: new Date().toISOString(),\\n      execution_id: $execution.id,\\n      workflow_id: $workflow.id,\\n      request_id: req.requestId,\\n      session_id: req.sessionId,\\n      user_id: req.userId,\\n      model: req.model,\\n      prompt: req.chatInput,\\n      response: String(responseText),\\n      intent: out.intent || \\"\\",\\n      confidence: toNum(out.confidence, 0),\\n      assumptions: JSON.stringify(\\n        Array.isArray(out.assumptions) ? out.assumptions : [],\\n      ),\\n      evidence: JSON.stringify(Array.isArray(out.evidence) ? out.evidence : []),\\n      uncertainty: out.uncertainty || \\"\\",\\n      limitations: JSON.stringify(\\n        Array.isArray(out.limitations) ? out.limitations : [],\\n      ),\\n      factual_claim_count: claims.length,\\n      unsupported_claim_count: unsupportedClaims,\\n      hallucination_rate: hallucinationRate,\\n      hallucination_risk: hallucinationRisk,\\n      bias_risk: biasRisk,\\n      safety_risk: String(out.safety_risk || \\"unknown\\").toLowerCase(),\\n      needs_review: needsReview,\\n      review_reason:\\n        out.review_reason ||\\n        (autoNeedsReview ? \\"auto-threshold-triggered\\" : \\"\\"),\\n      latency_ms: latencyMs,\\n      status: \\"success\\",\\n      token_source: tokenSource,\\n    },\\n  },\\n];\\n"},"id":"64c24bc4-2fa0-4b56-ba36-e55d55a0377f","name":"Format Observability Log","type":"n8n-nodes-base.code","typeVersion":2,"position":[1648,1328]},{"parameters":{},"type":"@n8n/n8n-nodes-langchain.memoryBufferWindow","typeVersion":1.3,"position":[1216,1552],"id":"4fce1fc7-d9c5-4798-804a-da35f49b7d69","name":"Simple Memory"},{"parameters":{"workflowId":{"__rl":true,"value":"R_oyuzd2t5rjLrFV3Dz_j","mode":"list","cachedResultUrl":"/workflow/R_oyuzd2t5rjLrFV3Dz_j","cachedResultName":"SUB07 - Parse String from AI to Json"},"workflowInputs":{"mappingMode":"defineBelow","value":{},"matchingColumns":[],"schema":[],"attemptToConvertTypes":false,"convertFieldsToString":true},"options":{}},"type":"n8n-nodes-base.executeWorkflow","typeVersion":1.3,"position":[1424,1328],"id":"bb2ae989-a9d6-4e62-8b9e-5681fcd963e0","name":"Call 'SUB07 - Parse String from AI to Json'"},{"parameters":{"operation":"append","documentId":{"__rl":true,"value":"https://docs.google.com/spreadsheets/d/1oMhA1Io5SRZg7rIxW7aJfbBQQCFCtgxlzgizZCLKQPQ/edit?usp=sharing","mode":"url"},"sheetName":{"__rl":true,"value":"log","mode":"name"},"columns":{"mappingMode":"autoMapInputData","value":{},"matchingColumns":[],"schema":[{"id":"timestamp","displayName":"timestamp","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"request_id","displayName":"request_id","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"session_id","displayName":"session_id","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"user_id","displayName":"user_id","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"model","displayName":"model","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"prompt","displayName":"prompt","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"response","displayName":"response","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"latency_ms","displayName":"latency_ms","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"input_tokens","displayName":"input_tokens","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"output_tokens","displayName":"output_tokens","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"total_tokens","displayName":"total_tokens","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"status","displayName":"status","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"intent","displayName":"intent","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"confidence","displayName":"confidence","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"hallucination_rate","displayName":"hallucination_rate","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"hallucination_risk","displayName":"hallucination_risk","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"bias_risk","displayName":"bias_risk","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"safety_risk","displayName":"safety_risk","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"needs_review","displayName":"needs_review","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"review_reason","displayName":"review_reason","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.googleSheets","typeVersion":4.7,"position":[1872,1232],"id":"a637aa68-8663-467b-9d0f-24a0c1769390","name":"Append row in sheet","credentials":{"googleSheetsOAuth2Api":{"id":"P3lLYJdhCQzsVc1E","name":"Google Sheets account [TK]"}}},{"parameters":{"options":{"responseMode":"responseNodes"}},"type":"@n8n/n8n-nodes-langchain.chatTrigger","typeVersion":1.4,"position":[624,1328],"id":"e2db8963-b5f3-48c2-a2d7-482d3ab0aed7","name":"When chat message received","webhookId":"78b3c2dc-4406-439f-8f4f-8a2fda937e78"},{"parameters":{"message":"={{ $json.response }}","options":{}},"type":"@n8n/n8n-nodes-langchain.chat","typeVersion":1.1,"position":[1872,1424],"id":"310419e0-3412-4e68-b168-9f74cc8b0204","name":"Chat","webhookId":"2e7205d9-fe44-4ce3-a283-fbf397a861f0"},{"parameters":{"content":"### (c) 2026 Candid GRC Co., Ltd. All Rights Reserved.\\n\\nThis workflow, including its structure, automation logic, integration, architecture, and embedded code, is proprietary intellectual property of Candid GRC Co., Ltd.\\n\\nUnauthorized reproduction, redistribution, reverse engineering, or commercial deployment is strictly prohibited without prior written consent.","height":156,"width":1136,"color":4},"id":"363c00f6-56ed-42a8-8d3b-e9bb054fc4f8","name":"Copyright Notice","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[592,1008]},{"parameters":{"content":"## Workflow Overview\\n\\nFlow นี้รับข้อความจาก chat, ส่งเข้า AI Agent เพื่อให้ตอบกลับเป็น JSON, แปลงผลลัพธ์เป็น object, แล้วคำนวณ metrics สำหรับ AI Observability ก่อนส่งคำตอบกลับและบันทึก log ลง Google Sheets.","height":164,"width":1456,"color":7},"id":"a4f966b2-9b37-4d09-8ce0-8b312d3e0f11","name":"Overview Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[592,1184]},{"parameters":{"content":"## 1) รับข้อความและเตรียม request\\n\\n`When chat message received` เปิดรับข้อความจากผู้ใช้\\n`Prepare Input + Start Timer` ดึง prompt จาก body/input, ตรวจว่าไม่ว่าง, สร้าง `requestId`, `sessionId`, `userId`, กำหนด model และบันทึกเวลาเริ่มต้นเพื่อใช้คำนวณ latency ภายหลัง","height":228,"width":432,"color":5},"id":"1ef31a9a-75df-4716-b00f-6b77d2f02cc6","name":"Input Stage Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[592,1600]},{"parameters":{"content":"## 2) ให้ AI ตอบแบบอธิบายได้\\n\\n`AI Agent` ใช้ system message บังคับให้ตอบเป็น JSON เท่านั้น และต้องแนบข้อมูล explainability เช่น intent, confidence, assumptions, evidence, limitations, factual claims รวมถึงความเสี่ยงด้าน hallucination, bias และ safety\\n\\n`Gemini 2.5 Flash` คือ LLM ที่ใช้ประมวลผล\\n`Simple Memory` เก็บบริบทบทสนทนาระยะสั้นให้ agent","height":276,"width":512,"color":6},"id":"920d9cdd-3552-4ef1-82a3-6d3bc6786af2","name":"Agent Stage Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[976,1680]},{"parameters":{"content":"## 3) แปลงข้อความ JSON ให้พร้อมใช้งาน\\n\\n`Call 'SUB07 - Parse String from AI to Json'` รับข้อความ JSON ที่ agent ส่งกลับมา แล้ว parse ให้เป็น object เพื่อให้ขั้นตอนถัดไปเข้าถึง field ต่าง ๆ ได้โดยตรง เช่น `answer`, `confidence`, `factual_claims` และ risk flags","height":212,"width":416,"color":3},"id":"7d5f0866-e4ab-4a85-9b6d-c85285afabcb","name":"Parse Stage Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[1392,1600]},{"parameters":{"content":"## 4) สร้าง observability log\\n\\n`Format Observability Log` รวมข้อมูล request และผลลัพธ์จาก AI เพื่อสร้างระเบียนสำหรับติดตามการทำงาน เช่น execution/workflow/request/session/user, prompt, response, latency, token source, factual claim count, unsupported claim count, hallucination rate และการตัดสินใจว่า `needs_review` หรือไม่\\n\\nถ้า hallucination สูงหรือ risk เป็น high ระบบจะตั้ง review flag อัตโนมัติ","height":292,"width":496,"color":4},"id":"794edfa1-0d3e-45b9-93df-a8fead448e95","name":"Observability Stage Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[1584,1648]},{"parameters":{"content":"## 5) ส่งคำตอบและเก็บ log\\n\\n`Chat` ส่งข้อความตอบกลับผู้ใช้จาก field `response`\\n`Append row in sheet` บันทึกข้อมูล observability ลง Google Sheets ชีต `log` เพื่อใช้ตรวจสอบย้อนหลัง ทำ dashboard หรือติดตามคุณภาพโมเดลในระดับ execution","height":212,"width":448,"color":2},"id":"f2ca28bf-d3c6-49ee-9f30-55b5d7084bc8","name":"Output Stage Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[1808,1600]},{"parameters":{"options":{"systemMessage":"=You are a helpful assistanYou are an AI Assistant for general-purpose question answering for users.\\n\\nPrimary responsibilities:\\n1) Provide clear, concise, and accurate answers to user questions.\\n2) Respond in Thai when the user writes in Thai.\\n3) If information is insufficient, state what is missing and ask a polite follow-up question.\\n4) Do not fabricate uncertain information; explicitly state \\"insufficient information available\\" when necessary.\\n5) Provide model behavior details for Explainability, Hallucination, and Bias.\\n6) Response in JSON format only.\\n\\nResponse format (JSON only):\\n{\\n  \\"answer\\": \\"Main answer for the user\\",\\n  \\"intent\\": \\"Short intent type such as explain/summarize/howto\\",\\n  \\"confidence\\": 0.0,\\n  \\"assumptions\\": [\\"Assumptions made\\"],\\n  \\"evidence\\": [\\"Evidence from prompt/context\\"],\\n  \\"uncertainty\\": \\"Areas of uncertainty\\",\\n  \\"limitations\\": [\\"Limitations of the answer\\"],\\n  \\"factual_claims\\": [\\n    {\\n      \\"claim\\": \\"A factual statement\\",\\n      \\"support_status\\": \\"supported|unsupported|unknown\\",\\n      \\"evidence\\": [\\"Evidence supporting the claim\\"]\\n    }\\n  ],\\n  \\"hallucination_risk\\": \\"low|medium|high\\",\\n  \\"bias_risk\\": \\"low|medium|high\\",\\n  \\"safety_risk\\": \\"low|medium|high\\",\\n  \\"needs_followup\\": false,\\n  \\"followup_question\\": \\"\\",\\n  \\"needs_review\\": false,\\n  \\"review_reason\\": \\"\\"\\n}\\n\\nRules:\\n- confidence must be a number between 0 and 1.\\n- If needs_followup = true, followup_question must be provided.\\n- If needs_review = true, review_reason must be provided.\\n- support_status must be one of: supported, unsupported, or unknown only.\\n- Do not include markdown, code blocks, or any text outside the JSON.\\n- The answer must be concise, easy to read, and no more than 6 lines.","returnIntermediateSteps":true}},"type":"@n8n/n8n-nodes-langchain.agent","typeVersion":3.1,"position":[1072,1328],"id":"e1111dde-5277-4e42-ade6-c474b5742da5","name":"AI Agent"}]	{"Prepare Input + Start Timer":{"main":[[{"node":"AI Agent","type":"main","index":0}]]},"Gemini 2.5 Flash":{"ai_languageModel":[[{"node":"AI Agent","type":"ai_languageModel","index":0}]]},"Simple Memory":{"ai_memory":[[{"node":"AI Agent","type":"ai_memory","index":0}]]},"Call 'SUB07 - Parse String from AI to Json'":{"main":[[{"node":"Format Observability Log","type":"main","index":0}]]},"Format Observability Log":{"main":[[{"node":"Chat","type":"main","index":0},{"node":"Append row in sheet","type":"main","index":0}]]},"When chat message received":{"main":[[{"node":"Prepare Input + Start Timer","type":"main","index":0}]]},"AI Agent":{"main":[[{"node":"Call 'SUB07 - Parse String from AI to Json'","type":"main","index":0}]]}}	2026-09-16 11:33:27.669+07	2026-09-16 11:33:27.669+07	{"executionOrder":"v1","binaryMode":"separate","availableInMCP":false}	\N	{}	7d3813ae-c1ee-4888-9b80-20f17e74d7fb	0	Mmwx74pQ3aGdzeD4VV92Q	{"templateCredsSetupCompleted":true,"instanceId":"20cf75cd0417fe5be3c3d8dcf7163bcd4dd5f0947193527bf3d55f850ac76577"}	f_example_02	f	1	\N	\N	[]	\N
