nce","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"uncertainty","displayName":"uncertainty","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"limitations","displayName":"limitations","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"factual_claim_count","displayName":"factual_claim_count","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"unsupported_claim_count","displayName":"unsupported_claim_count","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"hallucination_rate","displayName":"hallucination_rate","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"hallucination_risk","displayName":"hallucination_risk","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"bias_risk","displayName":"bias_risk","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"safety_risk","displayName":"safety_risk","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"needs_review","displayName":"needs_review","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"latency_ms","displayName":"latency_ms","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"input_tokens","displayName":"input_tokens","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"output_tokens","displayName":"output_tokens","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"total_tokens","displayName":"total_tokens","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"status","displayName":"status","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"token_source","displayName":"token_source","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true},{"id":"review_reason","displayName":"review_reason","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.googleSheets","typeVersion":4.7,"position":[1152,2192],"id":"ce58bc11-4ded-40b5-9fdf-62563090af93","name":"Append row in sheet","credentials":{"googleSheetsOAuth2Api":{"id":"P3lLYJdhCQzsVc1E","name":"Google Sheets account [TK]"}}},{"parameters":{"options":{"responseMode":"responseNodes"}},"type":"@n8n/n8n-nodes-langchain.chatTrigger","typeVersion":1.4,"position":[256,2288],"id":"31fad6fd-182f-4132-a1aa-654b72379cae","name":"When chat message received","webhookId":"78b3c2dc-4406-439f-8f4f-8a2fda937e78"},{"parameters":{"message":"={{ $json.response }}","options":{}},"type":"@n8n/n8n-nodes-langchain.chat","typeVersion":1.1,"position":[1152,2384],"id":"112108d8-889d-48a3-9022-4ddb843a49cd","name":"Chat","webhookId":"2e7205d9-fe44-4ce3-a283-fbf397a861f0"},{"parameters":{"content":"### (c) 2026 Candid GRC Co., Ltd. All Rights Reserved.\\n\\nThis workflow, including its structure, automation logic, integration, architecture, and embedded code, is proprietary intellectual property of Candid GRC Co., Ltd.\\n\\nUnauthorized reproduction, redistribution, reverse engineering, or commercial deployment is strictly prohibited without prior written consent.","height":156,"width":1136,"color":4},"id":"85aa93a4-f57e-4897-84f9-29f592910a10","name":"Copyright Notice","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[176,1984]},{"parameters":{"method":"POST","url":"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent","sendQuery":true,"queryParameters":{"parameters":[{"name":"key","value":"AIzaSyCVSYVQP9fXK8Wp_JMrvIFUwQLj949hGYI"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\\n  \\"system_instruction\\": {\\n    \\"parts\\": [\\n      {\\n        \\"text\\": \\"You are an AI assistant. Always respond ONLY with valid JSON (no markdown, no code fences). The JSON must contain exactly these fields:\\\\n- answer (string): your actual response\\\\n- intent (string): detected user intent, e.g. question, task, greeting\\\\n- confidence (number 0.0-1.0): how confident you are\\\\n- assumptions (array of strings): assumptions you made\\\\n- evidence (array of strings): facts or sources you referenced\\\\n- uncertainty (string): what you are uncertain about\\\\n- limitations (array of strings): known limitations of your answer\\\\n- factual_claims (array of {claim: string, support_status: \\\\\\"supported\\\\\\"|\\\\\\"unsupported\\\\\\"|\\\\\\"unknown\\\\\\"})\\\\n- bias_risk (\\\\\\"low\\\\\\"|\\\\\\"medium\\\\\\"|\\\\\\"high\\\\\\")\\\\n- hallucination_risk (\\\\\\"low\\\\\\"|\\\\\\"medium\\\\\\"|\\\\\\"high\\\\\\")\\\\n- safety_risk (\\\\\\"low\\\\\\"|\\\\\\"medium\\\\\\"|\\\\\\"high\\\\\\")\\\\n- needs_review (boolean)\\\\n- review_reason (string, empty if needs_review is false)\\"\\n      }\\n    ]\\n  },\\n  \\"contents\\": [\\n    {\\n      \\"parts\\": [\\n        {\\n          \\"text\\": \\"{{ $json.chatInput }}\\"\\n        }\\n      ]\\n    }\\n  ],\\n  \\"generationConfig\\": {\\n    \\"temperature\\": 0.7,\\n    \\"maxOutputTokens\\": 1200,\\n    \\"responseMimeType\\": \\"application/json\\"\\n  }\\n}","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.4,"position":[704,2288],"id":"38c302b1-525d-47cf-bfae-7a8c0aae927a","name":"HTTP Request"}]	{"Prepare Input + Start Timer":{"main":[[{"node":"HTTP Request","type":"main","index":0}]]},"Format Observability Log":{"main":[[{"node":"Chat","type":"main","index":0},{"node":"Append row in sheet","type