46c5c2f8-27f4-4de5-971e-cee2c4c6f49d	gjJjc-Y8drBH2mMVIIn7a	import	2026-09-16 11:33:27.669+07	2026-09-16 11:33:27.669+07	[{"parameters":{},"type":"n8n-nodes-base.manualTrigger","typeVersion":1,"position":[-176,-208],"id":"5198089e-b62f-4779-8ee9-d01caa62cdc1","name":"When clicking ‘Execute workflow’"},{"parameters":{"options":{}},"type":"n8n-nodes-tesseractjs.tesseractNode","typeVersion":1,"position":[160,-48],"id":"b9dedc4d-ef85-439a-a838-b9e6f48d6fd1","name":"Tesseract"},{"parameters":{"value":"={{ $json.text }}","width":256,"qrCodeOptions":{}},"type":"n8n-nodes-qrcode.qrCode","typeVersion":1,"position":[400,-48],"id":"a3c92eb2-f9ac-494d-879d-dd8fe8533cb4","name":"QrCode"},{"parameters":{"httpMethod":"POST","path":"image-to-qrcode","responseMode":"responseNode","options":{}},"type":"n8n-nodes-base.webhook","typeVersion":2.1,"position":[-192,128],"id":"01376d65-3332-4134-98a7-31c838e4556c","name":"Webhook","webhookId":"30cb6219-2d74-4af3-a7ea-e948890c1415"},{"parameters":{"respondWith":"binary","options":{}},"type":"n8n-nodes-base.respondToWebhook","typeVersion":1.5,"position":[656,-48],"id":"e3f2b6dd-a5fb-488c-aa4e-d8ba8271ba2f","name":"Respond to Webhook"},{"parameters":{"operation":"Convert from PDF","advancedOptions":{}},"type":"n8n-nodes-pdfco.PDFco Api","typeVersion":1,"position":[560,192],"id":"9f77e266-512f-424a-8cb7-740a308d205d","name":"PDFco Api","disabled":true},{"parameters":{"content":"### © 2026 Candid GRC Co., Ltd. All Rights Reserved.\\n\\nThis workflow, including its structure, automation logic, integration, architecture, and embedded code, is proprietary intellectual property of Candid GRC Co., Ltd.\\n\\nUnauthorized reproduction, redistribution, reverse engineering, or commercial deployment is strictly prohibited without prior written consent.","height":156,"width":1112,"color":4},"id":"5004dfe0-fe65-4466-9c66-ac000b839781","name":"Copyright Notice","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[-256,432]}]	{"When clicking ‘Execute workflow’":{"main":[[{"node":"Tesseract","type":"main","index":0}]]},"Tesseract":{"main":[[{"node":"QrCode","type":"main","index":0}]]},"Webhook":{"main":[[{"node":"Tesseract","type":"main","index":0}]]},"QrCode":{"main":[[{"node":"Respond to Webhook","type":"main","index":0}]]}}	\N	f	\N	[]
dec3b00e-1b99-4d6e-a967-4703c06378ec	8ZqbSTgROpRm8dONAhRIm	import	2026-09-16 11:33:27.669+07	2026-09-16 11:33:27.669+07	[{"parameters":{"content":"## OCR ใบเสร็จ / PDF สแกน\\n\\n**Flow:**\\n1. Webhook รับไฟล์ (รูป/PDF) โดยตรง\\n2. Unstructured API ทำ OCR\\n3. AI จัด structure ข้อมูล (ร้านค้า, วันที่, รายการ, ยอดรวม)\\n\\n**รับไฟล์:** multipart/form-data field ชื่อ `file`\\n**Unstructured:** http://unstructured-api:8000/general/v0/general","height":228,"width":664},"id":"f733c28e-79aa-4683-8122-c5499a88e281","name":"Overview","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[17392,-1168]},{"parameters":{"httpMethod":"POST","path":"ocr-receipt","responseMode":"responseNode","options":{"binaryPropertyName":"file"}},"id":"eaba33a9-5f38-412d-8a91-2f3c605d621b","name":"Webhook: Upload File","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[17408,-912],"webhookId":"ocr-receipt-webhook"},{"parameters":{"jsCode":"// รับไฟล์จาก webhook - multipart (field=file) หรือ raw binary\\nconst input = $input.first();\\nconst binaryKeys = input.binary ? Object.keys(input.binary) : [];\\nconst body = input.json?.body || {};\\n\\nif (!binaryKeys.length) {\\n  const hint = body.file && typeof body.file === 'string' && body.file.includes('/')\\n    ? ' (body.file เป็น path ไม่ใช่ไฟล์จริง - ตรวจสอบว่า Bruno/Client ส่งไฟล์เป็น File ไม่ใช่ Text)'\\n    : '';\\n  throw new Error('ไม่พบไฟล์ ส่ง multipart field=file หรือ raw binary' + hint);\\n}\\n\\nconst fileKey = binaryKeys.find(k => /^(file|data|document|image)(\\\\d*)$/.test(k)) || binaryKeys[0];\\nconst binaryData = input.binary[fileKey];\\nconst filename = binaryData.fileName || binaryData.file_name || 'document';\\n\\nreturn [{\\n  json: { filename, source_field: fileKey },\\n  binary: { data: binaryData }\\n}];"},"id":"bd2f699d-7843-4f51-ab05-c8345175d3a6","name":"Prepare File","type":"n8n-nodes-base.code","typeVersion":2,"position":[17632,-912]},{"parameters":{"method":"POST","url":"http://unstructured-api:8000/general/v0/general","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Accept","value":"application/json"}]},"sendBody":true,"contentType":"multipart-form-data","bodyParameters":{"parameters":[{"parameterType":"formBinaryData","name":"files","inputDataFieldName":"data"},{"name":"strategy","value":"hi_res"},{"name":"languages","value":"tha+eng"}]},"options":{"timeout":120000}},"id":"39b018ba-3c6e-4a16-a976-d85c78264cba","name":"Unstructured OCR","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[17856,-912]},{"parameters":{"jsCode":"// ดึงทุก element ไม่ตัดทิ้ง - รวม text จากทุก field ที่มี\\nconst allItems = $input.all();\\nconst metadata = $('Prepare File').first().json;\\nconst prepBinary = $('Prepare File').first().binary?.data;\\n\\nconst elements = allItems.length > 1 ? allItems.map(i => i.json) : (() => { const r = allItems[0]?.json; return Array.isArray(r) ? r : (r?.elements || [r]); })();\\nconst cleanElements = elements\\n  .filter(el => el && typeof el === 'object')\\n  .map((el, i) => {\\n    const text = (el.text || el.content || el.value || '').trim();\\n    const tableHtml = el.metadata?.text_as_html;\\n    return {\\n      idx: i + 1,\\n      type: el.type || 'Unknown',\\n      text: text || (tableHtml ? '[Table]' : ''),\\n      page: el.metadata?.page_number,\\n      ...(tableHtml && { table_html: tableHtml })\\n    };\\n  })\\n  .filter(el => el.text || el.table_html);\\n\\nif (!cleanElements.length) throw new Error('OCR ไม่พบข้อความในไฟล์');\\n\\nconst rawText = cleanElements.map(e => e.table_html ? e.table_html : e.text).filter(Boolean).join('\\\\n\\\\n');\\nconst fullContent = cleanElements.map(e => `[${e.idx}] ${e.type} (p${e.page || '?'}):\\\\n${(e.table_html || e.text || '').trim()}`).join('\\\\n---\\\\n');\\n\\nreturn [{\\n  json: {\\n    filename: metadata.filename,\\n    elements: cleanElements,\\n    raw_text: rawText,\\n    full_content: fullContent,\\n    word_count: rawText.split(/\\\\s+/).filter(w => w).length,\\n    element_count: cleanElements.length,\\n    image_base64: prepBinary?.data || null,\\n    mime_type: prepBinary?.mimeType || (metadata.filename?.match(/\\\\.(png|webp)$/i) ? 'image/png' : 'image/jpeg')\\n  }\\n}];"},"id":"431e4570-c512-4b81-aaa1-02388645161f","name":"Format OCR Text","type":"n8n-nodes-base.code","typeVersion":2,"position":[18080,-912]},{"parameters":{"method":"POST","url":"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=AIzaSyCkDJwDuYage0hR59-aNjdSr-oq0hAs-cg","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ contents: [{ parts: [{ text: 'ขั้นตอนที่ 1: แก้คำ OCR ที่อ่านผิด (เช่น ช่องว่างระหว่างตัวอักษรไทย \\"บ ิ ล เต ็ ม\\" -> \\"บิลเต็ม\\" รวมคำที่แยกผิดให้อ่านได้)\\\\nขั้นตอนที่ 2: จากข้อความที่แก้แล้ว สรุปเป็น JSON\\\\n\\\\nฟิลด์: vendor, address, phone, date, receipt_no, items (array {name, quantity, unit_price, amount}), subtotal, tax, total, payment_method, raw_notes. ใช้ค่าที่แก้แล้ว ไม่ใช้ค่าดิบจาก OCR\\\\n\\\\nตอบเป็น JSON เท่านั้น ไม่มีข้อความอื่น\\\\n\\\\n=== OCR Content (' + $json.element_count + ' elements) ===\\\\n' + $json.full_content }] }], generationConfig: { temperature: 0.1, maxOutputTokens: 8192 } }) }}","options":{"timeout":60000}},"id":"cd5ea1d5-2b5d-4971-9da9-5697395ba7fb","name":"AI: Structure Data (Gemini)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[18304,-912]},{"parameters":{"jsCode":"// รวมผลลัพธ์ OCR + AI structure + elements\\nconst ocrData = $('Format OCR Text').first().json;\\nconst aiResponse = $input.first().json;\\n\\nlet structured = null;\\nconst content = aiResponse.candidates?.[0]?.content?.parts?.[0]?.text;\\nif (content) {\\n  const parseJson = (s) => { if (!s || typeof s !== 'string') return null; try { return JSON.parse(s); } catch (_) { return null; } };\\n  let toParse = content.trim();\\n  const codeBlock = toParse.match(/```(?:json)?\\\\s*([\\\\s\\\\S]*?)(?:```|$)/);\\n  if (codeBlock && codeBlock[1]) toParse = codeBlock[1].trim();\\n  const braceMatch = toParse.match(/(\\\\{[\\\\s\\\\S]*)/);\\n  if (braceMatch) toParse = braceMatch[1];\\n  structured = parseJson(toParse);\\n  if (!structured && toParse.includes('{')) {\\n    let fixed = toParse;\\n    let escape = false, inStr = false;\\n    for (let i = 0; i < toParse.length; i++) {\\n      const c = toParse[i];\\n      if (escape) { escape = false; continue; }\\n      if (c === '\\\\\\\\') { escape = true; continue; }\\n      if (c === '\\"') inStr = !inStr;\\n    }\\n    if (inStr) fixed += '\\"';\\n    const stack = [];\\n    for (const c of fixed) { if (c === '{') stack.push('}'); else if (c === '[') stack.push(']'); else if (c === '}' || c === ']') stack.pop(); }\\n    fixed += stack.reverse().join('');\\n    structured = parseJson(fixed);\\n  }\\n  if (!structured) structured = { raw_parsed: content };\\n}\\n\\nreturn [{\\n  json: {\\n    success: true,\\n    filename: ocrData.filename,\\n    raw_text: ocrData.raw_text,\\n    full_content: ocrData.full_content,\\n    word_count: ocrData.word_count,\\n    element_count: ocrData.element_count,\\n    elements: ocrData.elements,\\n    structured\\n  }\\n}];"},"id":"cd87fe43-9fef-4083-b85b-f46c6073991b","name":"Format Response","type":"n8n-nodes-base.code","typeVersion":2,"position":[18528,-912]},{"parameters":{"method":"POST","url":"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=AIzaSyCkDJwDuYage0hR59-aNjdSr-oq0hAs-cg","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ contents: [{ parts: [{ text: 'สรุปใบเสร็จด้านล่างเป็นภาษาไทย 2-4 ประโยค กระชับ อ่านง่าย ระบุร้าน วันที่ รายการหลัก ยอดรวม\\\\n\\\\n' + JSON.stringify($json.structured, null, 2) }] }], generationConfig: { temperature: 0.3, maxOutputTokens: 1024 } }) }}","options":{"timeout":30000}},"id":"a44c5a18-fa99-406b-9644-ed488b717b89","name":"AI: Summary","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[18752,-912]},{"parameters":{"jsCode":"// รวม structured + summary\\nconst prev = $('Format Response').first().json;\\nconst summaryRes = $input.first().json;\\nconst summary = summaryRes.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';\\n\\nreturn [{ json: { ...prev, summary } }];"},"id":"1ac90380-4a71-4dc7-9447-71a096fa57dd","name":"Format Final","type":"n8n-nodes-base.code","typeVersion":2,"position":[18976,-912]},{"parameters":{"respondWith":"json","responseBody":"={{ $json }}","options":{}},"id":"fce09976-c24b-4051-9ddc-a10d16179dad","name":"Respond","type":"n8n-nodes-base.respondToWebhook","typeVersion":1.1,"position":[19200,-912]},{"parameters":{"content":"### © 2026 Candid GRC Co., Ltd. All Rights Reserved.\\n\\nThis workflow, including its structure, automation logic, integration, architecture, and embedded code, is proprietary intellectual property of Candid GRC Co., Ltd.\\n\\nUnauthorized reproduction, redistribution, reverse engineering, or commercial deployment is strictly prohibited without prior written consent.","height":156,"width":1112,"color":4},"id":"89e61bbf-e8c3-452c-a134-526a6779736a","name":"Copyright Notice","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[17392,-1344]}]	{"Webhook: Upload File":{"main":[[{"node":"Prepare File","type":"main","index":0}]]},"Prepare File":{"main":[[{"node":"Unstructured OCR","type":"main","index":0}]]},"Unstructured OCR":{"main":[[{"node":"Format OCR Text","type":"main","index":0}]]},"Format OCR Text":{"main":[[{"node":"AI: Structure Data (Gemini)","type":"main","index":0}]]},"AI: Structure Data (Gemini)":{"main":[[{"node":"Format Response","type":"main","index":0}]]},"Format Response":{"main":[[{"node":"AI: Summary","type":"main","index":0}]]},"AI: Summary":{"main":[[{"node":"Format Final","type":"main","index":0}]]},"Format Final":{"main":[[{"node":"Respond","type":"main","index":0}]]}}	\N	f	\N	[]
b45df5e7-4118-46e3-9df8-05f192487302	Aagi02urqNJtmE-aubCFI	import	2026-09-16 11:33:27.669+07	2026-09-16 11:33:27.669+07	[{"parameters":{},"type":"n8n-nodes-base.manualTrigger","typeVersion":1,"position":[0,0],"id":"530fa739-d523-4cba-bce7-cbfad6f12f6a","name":"When clicking ‘Execute workflow’"},{"parameters":{"operation":"download","fileId":{"__rl":true,"value":"https://drive.google.com/file/d/1kDPNiB3RtlgbxxkWSlBAP9hrvClsv4Be/view?usp=sharing","mode":"url"},"options":{}},"type":"n8n-nodes-base.googleDrive","typeVersion":3,"position":[224,0],"id":"265ecc94-a280-472a-9933-7aecf7c0c2ae","name":"Download file","credentials":{"googleDriveOAuth2Api":{"id":"lIazF92y73qsqOPU","name":"Google Drive account [DC]"}}},{"parameters":{"promptType":"define","text":"สกัดข้อมูลจากรูปภาพใบเสร็จที่ได้รับ","hasOutputParser":true,"options":{"systemMessage":"คุณคือผู้เชี่ยวชาญด้านการวิเคราะห์เอกสารทางการเงิน (OCR Specialist) หน้าที่ของคุณคือสกัดข้อมูลจากรูปภาพใบเสร็จที่ได้รับ ให้อยู่ในรูปแบบ JSON ที่มีโครงสร้างชัดเจน\\n\\nกฎเหล็ก:\\n1. หากอ่านข้อความไม่ออก ให้ใส่ค่าเป็น null\\n2. สรุปข้อมูลเป็นภาษาไทยในส่วนของชื่อร้านและรายการสินค้า\\n3. คืนค่ากลับมาเป็น JSON Object เท่านั้น ห้ามมีคำเกริ่นนำ\\n\\n","passthroughBinaryImages":true}},"type":"@n8n/n8n-nodes-langchain.agent","typeVersion":3.1,"position":[512,0],"id":"319572e1-a83c-40c2-87b0-83aaf4e285e6","name":"AI Agent"},{"parameters":{"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatGoogleGemini","typeVersion":1,"position":[432,224],"id":"97f703bb-f52a-4d26-bb9f-c24e3967bfd7","name":"Google Gemini Chat Model","credentials":{"googlePalmApi":{"id":"PesQLlxhmFqsaWL0","name":"Google Gemini(PaLM) Api account [DC]"}}},{"parameters":{"jsonSchemaExample":"\\n{\\n\\"store_name\\": \\"ชื่อร้านค้า\\",\\n\\"date\\": \\"วันที่ในรูปแบบ YYYY-MM-DD\\",\\n\\"total_amount\\": \\"ยอดรวมสุทธิ (ตัวเลข)\\",\\n\\"tax_amount\\": \\"ภาษีมูลค่าเพิ่ม (ถ้ามี)\\",\\n\\"items\\": [\\n{\\"name\\": \\"ชื่อสินค้า\\", \\"quantity\\": 1, \\"price\\": 0}\\n],\\n\\"currency\\": \\"สกุลเงิน (เช่น THB, USD)\\"\\n}"},"type":"@n8n/n8n-nodes-langchain.outputParserStructured","typeVersion":1.3,"position":[688,256],"id":"36bc910f-2772-4a0e-a933-dfbdac851c50","name":"Structured Output Parser"},{"parameters":{"mode":"raw","jsonOutput":"={{ $json.output }}\\n\\n","options":{}},"type":"n8n-nodes-base.set","typeVersion":3.4,"position":[912,0],"id":"4dcf1c5c-2a42-43f0-ab3f-f88ce117a806","name":"Edit Fields"},{"parameters":{"content":"### © 2026 Candid GRC Co., Ltd. All Rights Reserved.\\n\\nThis workflow, including its structure, automation logic, integration, architecture, and embedded code, is proprietary intellectual property of Candid GRC Co., Ltd.\\n\\nUnauthorized reproduction, redistribution, reverse engineering, or commercial deployment is strictly prohibited without prior written consent.","height":80,"width":1112,"color":4},"id":"7ce4274a-4dbc-4cac-a142-9ecc405a95e4","name":"Copyright Notice","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[-64,400]},{"parameters":{"content":"### 🧾 AI Receipt OCR Automation\\nWorkflow สำหรับดึงข้อมูลจากใบเสร็จอัตโนมัติด้วย Google Gemini AI\\n\\n---\\n#### 🚀 การทำงานของ Workflow (Step-by-Step)\\n1. **Trigger:** เริ่มต้นทำงานด้วยมือ (Manual)\\n2. **Fetch:** ดาวน์โหลดไฟล์ภาพใบเสร็จจาก Google Drive (ผ่าน URL)\\n3. **Process:** ส่งรูปภาพเข้า **AI Agent** เพื่อวิเคราะห์ข้อมูล\\n4. **Parse:** ใช้ **Structured Output Parser** เพื่อจัดระเบียบข้อมูลเป็น JSON\\n5. **Output:** จัดรูปแบบข้อมูลชุดสุดท้ายที่ Node **Edit Fields** พร้อมใช้งาน\\n\\n---\\n#### ⚠️ ข้อควรระวัง\\n* หากใบเสร็จยาวเกินไป หรือภาพเบลอ AI อาจจะคืนค่าเป็น `null` ตามกฎที่ตั้งไว้","height":352,"width":944},"type":"n8n-nodes-base.stickyNote","position":[0,-400],"typeVersion":1,"id":"8d6797bc-ba1e-47b3-8453-de204f96de46","name":"Sticky Note"}]	{"When clicking ‘Execute workflow’":{"main":[[{"node":"Download file","type":"main","index":0}]]},"Download file":{"main":[[{"node":"AI Agent","type":"main","index":0}]]},"Google Gemini Chat Model":{"ai_languageModel":[[{"node":"AI Agent","type":"ai_languageModel","index":0}]]},"Structured Output Parser":{"ai_outputParser":[[{"node":"AI Agent","type":"ai_outputParser","index":0}]]},"AI Agent":{"main":[[{"node":"Edit Fields","type":"main","index":0}]]}}	\N	f	\N	[]
097af7c0-f5ae-4173-9d4f-9f4fe6bc3074	nFU529aRlAJjlLtZ	CSIT NU	2026-09-18 10:32:56.986+07	2026-09-18 10:32:56.986+07	[{"parameters":{"content":"## 🤖 Workshop 1: AI Agent ผู้ช่วยครูประจำชั้น\\n\\n**วัตถุประสงค์:**\\n1. สร้าง AI Chatbot ผู้ช่วยครูด้วย **AI Agent Node**\\n2. เชื่อมต่อ **Google Gemini Chat Model** (`gemini-flash-latest` — alias ที่ชี้ไปยังรุ่น Flash ล่าสุดของ Gemini เสมอ ไม่ต้องแก้ชื่อโมเดลเองเมื่อ Google ปลดรุ่นเก่า)\\n3. จดจำบริบทการสนทนาด้วย **Window Buffer Memory**\\n\\n**วิธีทดสอบ:**\\nคลิกปุ่ม **Chat** ที่ด้านล่างขวาของ n8n แล้วพิมพ์ข้อความทดสอบ เช่น:\\n*\\"ช่วยวิเคราะห์คะแนนสอบเก็บคะแนนบทที่ 1 วิชาคณิตศาสตร์: สมชาย: 45/100, สมหญิง: 88/100, กิตติ: 62/100, วิภา: 38/100, ธนกร: 92/100\\"*","height":420,"width":1052,"color":2},"id":"38060958-6667-4c90-98ac-e808191148e4","name":"Sticky Note - ภาพรวมและวิธีใช้งาน","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[368,-320]},{"parameters":{"content":"## 🔑 สิ่งที่ต้องตั้งค่า (Credentials)\\n\\n1. **Google Gemini (PaLM) API Credential:**\\n   - สมัครและรับ API Key ฟรีที่ [Google AI Studio](https://aistudio.google.com/)\\n   - ดับเบิ้ลคลิกที่โหนด **Google Gemini Chat Model** แล้วเลือกหรือสร้าง Credential ใหม่ ใส่ API Key\\n2. **System Prompt ใน AI Agent:**\\n   - กำหนดบทบาทเป็น \\"ผู้ช่วยครูประจำชั้นอัจฉริยะ\\"\\n   - ระบุกฎการตอบให้สุภาพ ชัดเจน และนำไปปฏิบัติได้จริง","height":320,"width":484,"color":4},"id":"469be814-64e6-4247-8e77-2c6dcac157a4","name":"Sticky Note - การตั้งค่า Credential","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[976,144]},{"parameters":{"options":{}},"id":"652e9a49-a0f4-4607-915b-8846dfb33ead","name":"When chat message received","type":"@n8n/n8n-nodes-langchain.chatTrigger","typeVersion":1.1,"position":[432,144],"webhookId":"teacher-assistant-chat"},{"parameters":{"options":{"systemMessage":"=คุณคือผู้ช่วยครูประจำชั้นอัจฉริยะ (AI Teacher Assistant) ประจำโรงเรียน\\n\\nหน้าที่หลักของคุณคือ:\\n1. วิเคราะห์ผลการเรียนและพฤติกรรมของนักเรียนจากข้อมูลที่ครูป้อนเข้ามา\\n2. ค้นหานักเรียนกลุ่มเสี่ยง (คะแนนต่ำกว่าเกณฑ์หรือมีแนวโน้มต้องการความช่วยเหลือเร่งด่วน)\\n3. จัดทำรายงานสรุปผลสัมฤทธิ์ทางการเรียนอย่างกระชับ เข้าใจง่าย\\n4. เสนอแนะกิจกรรมเสริม กิจกรรมซ่อมเสริม และแนวทางการพัฒนาผู้เรียนเป็นรายบุคคล\\n\\nกฎการตอบ:\\n- สุภาพ เป็นทางการ กระชับ เป็นระเบียบ (ใช้ Bullet points หรือตารางสรุป)\\n- ให้ข้อเสนอแนะเชิงบวกที่ครูสามารถนำไปปฏิบัติจริงในห้องเรียนได้\\n- หากมีการคำนวณคะแนน ให้ระบุค่าเฉลี่ย, คะแนนสูงสุด-ต่ำสุด และอัตราการผ่านเกณฑ์อย่างถูกต้อง"}},"id":"0fe09471-99d4-4631-b1cb-50d2a9749ac3","name":"AI Agent (Teacher Assistant)","type":"@n8n/n8n-nodes-langchain.agent","typeVersion":1.7,"position":[640,144]},{"parameters":{"modelName":"models/gemini-flash-latest","options":{"temperature":0.3}},"id":"d878c630-61a1-4cf2-aee6-7af8d9496417","name":"Google Gemini Chat Model","type":"@n8n/n8n-nodes-langchain.lmChatGoogleGemini","typeVersion":1,"position":[592,368]},{"parameters":{"contextWindowLength":10},"id":"5379aa8b-0e1f-40fe-b516-c9b2a5df9dbe","name":"Window Buffer Memory","type":"@n8n/n8n-nodes-langchain.memoryBufferWindow","typeVersion":1.3,"position":[752,368]}]	{"When chat message received":{"main":[[]]},"Google Gemini Chat Model":{"ai_languageModel":[[]]},"Window Buffer Memory":{"ai_memory":[[]]}}	\N	t	\N	[]
56f21482-ee23-40ae-84a2-2aa7643a2606	1rxL7XWLR36DjtRwzwV53	import	2026-09-16 11:33:27.669+07	2026-09-16 11:33:27.669+07	[{"parameters":{"httpMethod":"POST","path":"ingest","responseMode":"responseNode","options":{}},"type":"n8n-nodes-base.webhook","typeVersion":2,"position":[784,288],"id":"e13ab60f-6891-4205-a663-25b2d6bf0336","name":"Webhook Trigger","webhookId":"rag-ingest-webhook"},{"parameters":{"jsCode":"/*\\n * Candid GRC Co., Ltd.\\n * Copyright © 2026 Candid GRC Co., Ltd.\\n * All Rights Reserved.\\n *\\n * This source code is proprietary and confidential.\\n * Unauthorized copying, modification, redistribution,\\n * reverse engineering, or commercial use is strictly prohibited.\\n *\\n * This code forms part of the Candid GRC Automation Framework.\\n */\\n\\nconst url = $json.body.url;\\nconst isPDF =\\n  url.toLowerCase().endsWith(\\".pdf\\") ||\\n  url.toLowerCase().includes(\\".pdf?\\") ||\\n  url.toLowerCase().includes(\\".pdf#\\");\\nreturn [{ json: { url, isPDF } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1008,192],"id":"adb9b29a-39b3-4691-9b0a-467f5a9854e1","name":"Detect Content Type"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"id":"69252de4-dcbe-42ef-b37f-73450b8a4841","leftValue":"={{ $json.isPDF }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2,"position":[1232,192],"id":"b686c0d2-3194-4172-b5ff-f4b08d567655","name":"Is PDF?"},{"parameters":{"url":"={{ $json.url }}","options":{"response":{"response":{"responseFormat":"file"}},"timeout":60000}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1456,96],"id":"78393b75-c8c8-4e21-b025-942953236998","name":"Fetch PDF"},{"parameters":{"method":"POST","url":"http://unstructured-api:8000/general/v0/general","sendBody":true,"contentType":"multipart-form-data","bodyParameters":{"parameters":[{"parameterType":"formBinaryData","name":"files","inputDataFieldName":"data"},{"name":"strategy","value":"auto"}]},"options":{"timeout":120000}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1680,96],"id":"7bd06b78-2aa0-4515-b061-c21667580636","name":"Parse PDF (Unstructured)"},{"parameters":{"method":"POST","url":"http://browserless:3000/content","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ url: $json.url, gotoOptions: { waitUntil: 'networkidle2', timeout: 60000 } }) }}","options":{"timeout":60000}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1680,288],"id":"2f46b09d-b0d6-4445-a816-c1c73d2c991c","name":"Fetch HTML (Browserless)"},{"parameters":{"jsCode":"/*\\n * Candid GRC Co., Ltd.\\n * Copyright © 2026 Candid GRC Co., Ltd.\\n * All Rights Reserved.\\n *\\n * This source code is proprietary and confidential.\\n * Unauthorized copying, modification, redistribution,\\n * reverse engineering, or commercial use is strictly prohibited.\\n *\\n * This code forms part of the Candid GRC Automation Framework.\\n */\\n\\n// Extract text from Browserless /content response (already plain text)\\nlet fullText = \\"\\";\\nconst data = items[0].json;\\n\\nif (typeof data === \\"string\\") {\\n  fullText = data;\\n} else if (data.data) {\\n  fullText = data.data;\\n} else {\\n  fullText = JSON.stringify(data);\\n}\\n\\n// Clean up HTML tags if any remain\\nfullText = fullText\\n  .replace(/<[^>]*>/g, \\" \\")\\n  .replace(/\\\\s+/g, \\" \\")\\n  .trim();\\n\\nconst url = $(\\"Detect Content Type\\").item.json.url;\\nreturn [{ json: { fullText, url } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1904,288],"id":"f2ae4ced-7ef1-4300-bd2d-7dc7d1a42bfc","name":"Extract HTML Text"},{"parameters":{},"type":"n8n-nodes-base.merge","typeVersion":3,"position":[2128,192],"id":"22845dc2-f3c9-4b38-ae7b-9d12d971436f","name":"Merge Paths"},{"parameters":{"operation":"insert","schema":{"__rl":true,"mode":"list","value":"public"},"table":{"__rl":true,"value":"documents","mode":"name"},"columns":{"mappingMode":"defineBelow","value":{"url":"={{ $json.url }}","status":"processing","updated_at":"={{ $now }}"},"matchingColumns":["url"],"schema":[{"id":"url","displayName":"url","required":false,"defaultMatch":true,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false},{"id":"status","displayName":"status","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":false,"removed":false},{"id":"updated_at","displayName":"updated_at","required":false,"defaultMatch":false,"display":true,"type":"dateTime","canBeUsedToMatch":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[2352,192],"id":"75f19794-339a-4e9f-9ef1-3729341d022a","name":"Create Document Record","credentials":{"postgres":{"id":"OIRne7MBoP0lCFbe","name":"Postgres account"}}},{"parameters":{"jsCode":"/*\\n * Candid GRC Co., Ltd.\\n * Copyright © 2026 Candid GRC Co., Ltd.\\n * All Rights Reserved.\\n *\\n * This source code is proprietary and confidential.\\n * Unauthorized copying, modification, redistribution,\\n * reverse engineering, or commercial use is strictly prohibited.\\n *\\n * This code forms part of the Candid GRC Automation Framework.\\n */\\n\\n// Split text into ~1000 character chunks with overlap\\nconst fullText = $(\\"Merge Paths\\").first().json.fullText;\\n// Use items[0].json.id because input comes from Postgres node which returns an array\\nconst documentId = items[0] ? items[0].json.id : 0;\\n\\nif (!fullText || fullText.length === 0) {\\n  throw new Error(\\n    \\"No text content available to chunk. Please check the Extraction steps.\\",\\n  );\\n}\\n\\nconst CHUNK_SIZE = 1000;\\nconst OVERLAP = 100;\\nconst chunks = [];\\n\\nfor (let i = 0; i < fullText.length; i += CHUNK_SIZE - OVERLAP) {\\n  const chunk = fullText.substring(i, i + CHUNK_SIZE).trim();\\n  if (chunk.length > 50) {\\n    chunks.push({\\n      json: {\\n        content: chunk,\\n        chunk_index: chunks.length,\\n        document_id: documentId,\\n      },\\n    });\\n  }\\n}\\n\\nreturn chunks;\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2576,96],"id":"3d8edc0f-3281-4982-b038-ec2cbf1d80de","name":"Split into Chunks"},{"parameters":{"method":"POST","url":"=https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-001:embedContent?key=AIzaSyCVSYVQP9fXK8Wp_JMrvIFUwQLj949hGYI","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'models/gemini-embedding-001', content: { parts: [{ text: $json.content }] }, outputDimensionality: 768 }) }}","options":{"batching":{"batch":{"batchSize":1,"batchInterval":768}}}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[2800,96],"id":"c2adeadc-8826-49fc-9980-381c2032e471","name":"Generate Chunk Embeddings"},{"parameters":{"operation":"insert","schema":{"__rl":true,"mode":"list","value":"public"},"table":{"__rl":true,"value":"document_chunks","mode":"name"},"columns":{"mappingMode":"defineBelow","value":{"document_id":"={{ $('Split into Chunks').item.json.document_id }}","content":"={{ $('Split into Chunks').item.json.content }}","embedding":"={{ JSON.stringify($json.embedding.values) }}","chunk_index":"={{ $('Split into Chunks').item.json.chunk_index }}"},"matchingColumns":[],"schema":[{"id":"document_id","displayName":"document_id","required":false,"defaultMatch":false,"display":true,"type":"number","canBeUsedToMatch":true,"removed":false},{"id":"content","displayName":"content","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":false,"removed":false},{"id":"embedding","displayName":"embedding","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":false,"removed":false},{"id":"chunk_index","displayName":"chunk_index","required":false,"defaultMatch":false,"display":true,"type":"number","canBeUsedToMatch":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[3024,96],"id":"d670a788-28c1-4fdc-9ebc-c9a2ff2954a7","name":"Store Chunks in Postgres","credentials":{"postgres":{"id":"OIRne7MBoP0lCFbe","name":"Postgres account"}}},{"parameters":{"method":"POST","url":"=https://generativelanguage.googleapis.com/v1/models/gemini-2.5-flash:generateContent?key=AIzaSyCVSYVQP9fXK8Wp_JMrvIFUwQLj949hGYI","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ contents: [{ parts: [{ text: 'คุณเป็นผู้เชี่ยวชาญด้านการสรุปเนื้อหา กรุณาสรุปเอกสารต่อไปนี้เป็นภาษาไทยอย่างครอบคลุม ครบถ้วน และเข้าใจง่าย:\\\\n\\\\n' + $('Merge Paths').item.json.fullText.substring(0, 30000) }] }], generationConfig: { temperature: 0.7, maxOutputTokens: 2048 } }) }}","options":{"timeout":60000}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[2576,288],"id":"a9bf8faf-2ed9-4c8f-97bf-b16567d2d7a9","name":"Generate Thai Summary (HTTP)"},{"parameters":{"operation":"update","schema":{"__rl":true,"mode":"list","value":"public"},"table":{"__rl":true,"value":"documents","mode":"name"},"columns":{"mappingMode":"defineBelow","value":{"id":"={{ $('Create Document Record').item.json.id }}","summary":"={{ $json.candidates[0].content.parts[0].text }}","status":"processed","updated_at":"={{ $now }}"},"matchingColumns":["id"],"schema":[{"id":"id","displayName":"id","required":false,"defaultMatch":true,"display":true,"type":"number","canBeUsedToMatch":true,"removed":false},{"id":"summary","displayName":"summary","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":false,"removed":false},{"id":"status","displayName":"status","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":false,"removed":false},{"id":"updated_at","displayName":"updated_at","required":false,"defaultMatch":false,"display":true,"type":"dateTime","canBeUsedToMatch":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[2800,288],"id":"14b5b4e7-aac3-4e09-9bf9-fade8e42b9fc","name":"Save Summary to Documents","credentials":{"postgres":{"id":"OIRne7MBoP0lCFbe","name":"Postgres account"}}},{"parameters":{"respondWith":"json","responseBody":"={{ { success: true, message: 'Document ingested successfully', url: $('Detect Content Type').first().json.url } }}","options":{}},"type":"n8n-nodes-base.respondToWebhook","typeVersion":1.1,"position":[3024,288],"id":"f4db02ba-e1fa-4bd1-957b-88588dad4d9d","name":"Respond Success"},{"parameters":{"operation":"executeQuery","query":"-- =============================================================\\n-- RAG System Database Initialization\\n-- PostgreSQL + pgvector (Dimension: 768 for Gemini embedding-001)\\n-- =============================================================\\n\\n-- 1. Enable the pgvector extension\\nCREATE EXTENSION IF NOT EXISTS vector;\\n\\n-- 2. Documents table — stores metadata about each ingested source\\nCREATE TABLE IF NOT EXISTS documents (\\n    id          SERIAL PRIMARY KEY,\\n    url         TEXT NOT NULL UNIQUE,\\n    summary     TEXT,\\n    status      TEXT DEFAULT 'pending',\\n    created_at  TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,\\n    updated_at  TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\\n);\\n\\n-- 3. Document chunks table — stores text chunks with vector embeddings\\nCREATE TABLE IF NOT EXISTS document_chunks (\\n    id            SERIAL PRIMARY KEY,\\n    document_id   INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,\\n    content       TEXT NOT NULL,\\n    embedding     vector(768),\\n    chunk_index   INTEGER,\\n    created_at    TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\\n);\\n\\n-- 4. HNSW index for fast cosine-similarity search\\nCREATE INDEX IF NOT EXISTS idx_document_chunks_embedding_hnsw\\n   ON document_chunks\\n   USING hnsw (embedding vector_cosine_ops);\\n\\n-- 5. Index on document_id for fast joins\\nCREATE INDEX IF NOT EXISTS idx_document_chunks_document_id\\n    ON document_chunks (document_id);\\n","options":{}},"type":"n8n-nodes-base.postgres","typeVersion":2.5,"position":[768,720],"id":"c58f936d-2796-4ae8-a3dc-ddbab37990c7","name":"Create Table","credentials":{"postgres":{"id":"OIRne7MBoP0lCFbe","name":"Postgres account"}}},{"parameters":{},"type":"n8n-nodes-base.manualTrigger","typeVersion":1,"position":[784,96],"id":"da6bf3f6-da88-4d04-922b-584da7e0df44","name":"When clicking ‘Execute workflow’"},{"parameters":{"content":"### © 2026 Candid GRC Co., Ltd. All Rights Reserved.\\n\\nThis workflow, including its structure, automation logic, integration, architecture, and embedded code, is proprietary intellectual property of Candid GRC Co., Ltd.\\n\\nUnauthorized reproduction, redistribution, reverse engineering, or commercial deployment is strictly prohibited without prior written consent.","height":156,"width":1112,"color":4},"id":"97baa214-45ac-4373-8761-db03f4c9e6a3","name":"Copyright Notice","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[720,-336]},{"parameters":{"content":"### Step 0: เตรียมโครงสร้างฐานข้อมูล (One-time Setup)\\n\\n- โหนดนี้ใช้สร้างตาราง `documents` และ `document_chunks` พร้อม pgvector\\n- ใช้ตอนเริ่มโปรเจกต์หรือ reset environment\\n- ถ้าตารางมีอยู่แล้ว `CREATE TABLE IF NOT EXISTS` จะไม่แก้ type เดิม","height":396,"width":408,"color":5},"id":"1f527b79-43b3-4bf1-b915-0cbfa6084e1b","name":"Note - DB Setup","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[624,496]},{"parameters":{"content":"### Step 1: รับ Request และแยกประเภทคอนเทนต์\\n\\n- เริ่มจาก Webhook รับ `body.url`\\n- `Detect Content Type` ตรวจว่าเป็น PDF หรือ HTML\\n- `Is PDF?` ทำ routing เพื่อเลือก pipeline ที่เหมาะกับข้อมูล","height":182,"width":440,"color":3},"id":"9fc4d9c6-49aa-47a2-931f-0dee4830a0a0","name":"Note - Trigger and Routing","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[720,-144]},{"parameters":{"content":"### Step 2A: PDF Extraction Path\\n\\n- `Fetch PDF` ดาวน์โหลดไฟล์เป็น binary\\n- `Parse PDF (Unstructured)` แปลงไฟล์เป็นองค์ประกอบข้อความ\\n- `Extract PDF Text` รวมข้อความเป็น `fullText` สำหรับขั้นตอนถัดไป","height":188,"width":580,"color":6},"id":"b3763fc6-4955-486e-af0d-891e4fe7bbde","name":"Note - PDF Path","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[1424,-144]},{"parameters":{"content":"### Step 2B: HTML Extraction Path\\n\\n- `Fetch HTML (Browserless)` render หน้าเว็บแล้วดึง content\\n- `Extract HTML Text` ทำความสะอาด text (ลบ tag/ช่องว่างเกิน)\\n- ส่งออกเป็น `fullText` รูปแบบเดียวกับ PDF path","height":188,"width":468,"color":6},"id":"b0784304-c181-4b69-9702-9bd188eaf0b9","name":"Note - HTML Path","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[1632,480]},{"parameters":{"content":"### Step 3: Merge + ลงทะเบียนเอกสาร\\n\\n- `Merge Paths` รวมผลจาก PDF/HTML ให้เหลือทางเดียว\\n- `Create Document Record` upsert เอกสารในตาราง `documents`\\n- ได้ `document_id` เพื่อใช้เป็น foreign key สำหรับ chunks","height":198,"width":430,"color":3},"id":"c9215ef9-5b56-4b03-86e1-d9163621ae5b","name":"Note - Merge and Document","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[2096,-144]},{"parameters":{"content":"### Step 4: Text Chunking\\n\\n- `Split into Chunks` ตัดข้อความเป็นช่วงขนาด ~1000 ตัวอักษร\\n- ใช้ overlap 100 เพื่อคงบริบทข้ามช่วง\\n- แต่ละ chunk มี `chunk_index` และ `document_id` ชัดเจน","height":192,"width":404,"color":7},"id":"e258cddf-3633-4a04-861b-3bb69398eb8b","name":"Note - Chunking","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[2560,-144]},{"parameters":{"content":"### Step 5: Embedding + Vector Storage\\n\\n- `Generate Chunk Embeddings` เรียก Gemini embedding\\n- บังคับ `outputDimensionality: 768` ให้ตรง schema\\n- `Store Chunks in Postgres` บันทึก vector ด้วย `::vector(768)`","height":188,"width":468,"color":5},"id":"a35099a1-dbf0-4bdb-8590-6426be8e91f6","name":"Note - Embedding Storage","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3024,-144]},{"parameters":{"content":"### Step 6: Thai Summary + Final Response\\n\\n- `Generate Thai Summary (HTTP)` สรุปใจความสำคัญเป็นภาษาไทย\\n- `Save Summary to Documents` อัปเดต status เป็น `processed`\\n- `Respond Success` ส่งผลลัพธ์กลับ caller","height":182,"width":472,"color":3},"id":"591b6807-5591-4710-9e02-ce5bb4eb2dc8","name":"Note - Summary and Response","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[2528,480]},{"parameters":{"content":"### ML-style Checklist (สำคัญมาก)\\n\\n1. มิติ embedding ต้องตรงกันทุกจุด: API output, SQL cast, DB schema\\n2. ถ้าเปลี่ยนมิติ ต้อง migrate column ไม่ใช่แค่แก้ workflow\\n3. ทดสอบทั้งเส้น PDF และ HTML ก่อนเปิดใช้งานจริง","height":188,"width":520,"color":4},"id":"e627b39a-3ddc-4783-ab4b-9f63ff8edff7","name":"Note - Quality Checklist","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3072,480]},{"parameters":{"jsCode":"/*\\n * Candid GRC Co., Ltd.\\n * Copyright © 2026 Candid GRC Co., Ltd.\\n * All Rights Reserved.\\n *\\n * This source code is proprietary and confidential.\\n * Unauthorized copying, modification, redistribution,\\n * reverse engineering, or commercial use is strictly prohibited.\\n *\\n * This code forms part of the Candid GRC Automation Framework.\\n */\\n\\n// Read all incoming items from Parse PDF (Unstructured).\\nconst inputItems = $input.all();\\nconst textChunks = [];\\n\\nfor (const item of inputItems) {\\n  const payload = item.json || {};\\n\\n  // Most common Unstructured shape after n8n item-splitting: { text: \\"...\\" }\\n  if (typeof payload.text === \\"string\\" && payload.text.trim()) {\\n    textChunks.push(payload.text.trim());\\n    continue;\\n  }\\n\\n  // Some setups return nested arrays/objects.\\n  if (Array.isArray(payload.elements)) {\\n    for (const el of payload.elements) {\\n      if (typeof el?.text === \\"string\\" && el.text.trim()) {\\n        textChunks.push(el.text.trim());\\n      }\\n    }\\n    continue;\\n  }\\n\\n  if (Array.isArray(payload.data)) {\\n    for (const el of payload.data) {\\n      if (typeof el?.text === \\"string\\" && el.text.trim()) {\\n        textChunks.push(el.text.trim());\\n      }\\n    }\\n  }\\n}\\n\\nconst fullText = textChunks.join(\\"\\\\n\\").trim();\\n\\n// Keep URL only if it is present in the incoming items.\\nconst urlItem = inputItems.find((i) => typeof i.json?.url === \\"string\\" && i.json.url);\\nconst url = urlItem ? urlItem.json.url : null;\\n\\nreturn [{\\n  json: {\\n    fullText,\\n    url,\\n  },\\n}];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1904,96],"id":"ecb206a1-ec4f-4edf-9426-e1d185e3d5ad","name":"Extract PDF Text"}]	{"Webhook Trigger":{"main":[[{"node":"Detect Content Type","type":"main","index":0}]]},"Detect Content Type":{"main":[[{"node":"Is PDF?","type":"main","index":0}]]},"Is PDF?":{"main":[[{"node":"Fetch PDF","type":"main","index":0}],[{"node":"Fetch HTML (Browserless)","type":"main","index":0}]]},"Fetch PDF":{"main":[[{"node":"Parse PDF (Unstructured)","type":"main","index":0}]]},"Parse PDF (Unstructured)":{"main":[[{"node":"Extract PDF Text","type":"main","index":0}]]},"Fetch HTML (Browserless)":{"main":[[{"node":"Extract HTML Text","type":"main","index":0}]]},"Extract HTML Text":{"main":[[{"node":"Merge Paths","type":"main","index":1}]]},"Merge Paths":{"main":[[{"node":"Create Document Record","type":"main","index":0}]]},"Create Document Record":{"main":[[{"node":"Split into Chunks","type":"main","index":0},{"node":"Generate Thai Summary (HTTP)","type":"main","index":0}]]},"Split into Chunks":{"main":[[{"node":"Generate Chunk Embeddings","type":"main","index":0}]]},"Generate Chunk Embeddings":{"main":[[{"node":"Store Chunks in Postgres","type":"main","index":0}]]},"Generate Thai Summary (HTTP)":{"main":[[{"node":"Save Summary to Documents","type":"main","index":0}]]},"Save Summary to Documents":{"main":[[{"node":"Respond Success","type":"main","index":0}]]},"When clicking ‘Execute workflow’":{"main":[[{"node":"Detect Content Type","type":"main","index":0}]]},"Extract PDF Text":{"main":[[{"node":"Merge Paths","type":"main","index":0}]]}}	\N	f	\N	[]
